def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for row in rows:
        updated_dt = parse_updated(row["updated"])
        item = {
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": opted_out(row["opted_out"]),
            "updated_dt": updated_dt,
        }
        if item["email"] or item["phone"]:
            prepared.append((len(prepared), item))

    # Union-find connects duplicate records transitively.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    seen_emails = {}
    seen_phone_names = {}
    for i, (_, item) in enumerate(prepared):
        if item["email"]:
            if item["email"] in seen_emails:
                union(i, seen_emails[item["email"]])
            else:
                seen_emails[item["email"]] = i

        if item["phone"] and item["last_name"]:
            key = (item["phone"], item["last_name"].casefold())
            if key in seen_phone_names:
                union(i, seen_phone_names[key])
            else:
                seen_phone_names[key] = i

    groups = {}
    for i, (original_index, item) in enumerate(prepared):
        groups.setdefault(find(i), []).append((original_index, item))

    def choose(group, field, valid_only=False):
        candidates = [
            (index, item) for index, item in group
            if item[field] and (not valid_only or item[field])
        ]
        if not candidates:
            return ""
        # Manual source first, then newest update, then earliest input row.
        _, selected = min(
            candidates,
            key=lambda pair: (
                pair[1]["source"] != "manual",
                -pair[1]["updated_dt"].timestamp(),
                pair[0],
            ),
        )
        return selected[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(index for index, _ in g)):
        latest = max(item["updated_dt"] for _, item in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(set().union(*(item["tags"] for _, item in group)))),
            "opted_out": "Y" if any(item["opted_out"] for _, item in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
